constexpr bool matches(const Rule &rule, const Query &q)
{
	for (int i = 0; i < rule.matched; ++i)
	{
		if (KEYS[i] == Key::Type ? rule.type != q.type : rule.values[i] != keyValue(KEYS[i], q))
			return false;
	}
	return true;
}

/// The cost to settle up front. Never affects results, only who pays.
constexpr int target(const Query &q, int point = ACTIVE_POINT)
{
	for (const Rule &rule : RULES)
		if (matches(rule, q))
		{
			long long depth = rule.depth[point];
			if (PER_SIZE)
				depth = depth * (q.width + q.height) / PER_SIZE_SCALE;
			return int(depth < MIN_DEPTH ? MIN_DEPTH : depth > MAX_DEPTH ? MAX_DEPTH : depth);
		}
	return MAX_DEPTH;
}
